<div class="admin-page-head"><h1>دسته‌بندی محصولات</h1><?= CHtml::link('بازگشت',array('adminCategory/index'),array('class'=>'btn btn-outline')) ?></div>
<section class="panel narrow-panel"><?php $form=$this->beginWidget('CActiveForm'); ?><?= $form->errorSummary($model) ?><div class="field"><label>نام دسته‌بندی</label><?= $form->textField($model,'name',array('required'=>true)) ?></div><div class="field"><label>شناسه انگلیسی</label><?= $form->textField($model,'slug',array('dir'=>'ltr')) ?></div><div class="field"><label>دسته والد</label><?= $form->dropDownList($model,'parent_id',Category::options($model->id),array('prompt'=>'دسته اصلی / بدون والد')) ?></div><div class="field"><label>ترتیب نمایش</label><?= $form->numberField($model,'sort_order',array('min'=>0)) ?></div><div class="field"><label>توضیحات</label><?= $form->textArea($model,'description',array('class'=>'markdown-editor','rows'=>6)) ?></div><?php $this->widget('MediaPicker',array('name'=>'image_id','value'=>CmsMedia::ids($model->image),'multiple'=>false,'label'=>'تصویر دسته‌بندی')); ?><?= CHtml::submitButton('ذخیره دسته‌بندی',array('class'=>'btn btn-primary')) ?><?php $this->endWidget(); ?></section>
<?php if(!$model->isNewRecord): ?><?= CHtml::beginForm(array('adminCategory/delete','id'=>$model->id),'post',array('data-confirm'=>'دسته حذف شود؟')) ?><?= CHtml::submitButton('حذف دسته',array('class'=>'btn btn-danger')) ?><?= CHtml::endForm() ?><?php endif; ?>
